// Demo build only: simulated password managers. Each demo provider carries the real provider's metadata
// (name, account form, capabilities – generated by demo/build.mjs) but keeps its vault in sessionStorage
// instead of talking to a server or a command-line tool. Sample data: demo/data.js.
import { DEMO_VAULTS } from './demo-data.js';

const KEY = 'omnivault-demo:vaults';
const load = () => { try { return JSON.parse(sessionStorage.getItem(KEY) ?? '{}'); } catch { return {}; } };
const save = (v) => { try { sessionStorage.setItem(KEY, JSON.stringify(v)); } catch { /* memory only */ } };
let vaults = load();

function vaultOf(config) {
  if (!vaults[config.id]) {
    const seed = DEMO_VAULTS[config.demo] ?? { folders: [], items: [] };
    vaults[config.id] = { folders: structuredClone(seed.folders), items: structuredClone(seed.items), trash: [] };
    save(vaults);
  }
  return vaults[config.id];
}
const commit = () => save(vaults);
const uid = () => crypto.randomUUID();

/** The item as the background sees it: account, provider and folder name filled in. */
function present(meta, config, vault, i) {
  return { ...structuredClone(i), accountId: config.id, provider: meta.id, folder: vault.folders.find((f) => f.id === i.folderId)?.name };
}

/** Same subtitle rules as the real providers (cards: brand and last four digits; identities: name or e-mail). */
function subtitle(i) {
  if (i.card) return [i.card.brand, i.card.number ? `*${String(i.card.number).replace(/\s/g, '').slice(-4)}` : ''].filter(Boolean).join(' ');
  if (i.identity) return [i.identity.firstName, i.identity.lastName].filter(Boolean).join(' ') || i.identity.email;
  return undefined;
}

export function demoProvider(meta) {
  const caps = meta.capabilities ?? {};
  const p = {
    ...meta,

    async login(config) {
      return { status: 'ok', session: { demo: true, at: Date.now() } };
    },

    async sync(config) {
      const v = vaultOf(config);
      return {
        items: v.items.map((i) => present(meta, config, v, i)),
        trash: caps.trash ? v.trash.map((i) => present(meta, config, v, i)) : [],
        folders: structuredClone(v.folders).sort((a, b) => a.name.localeCompare(b.name, 'de')),
      };
    },

    async saveItem(config, session, existing, data) {
      const v = vaultOf(config);
      const old = existing ? v.items.find((i) => i.id === existing.id) : null;
      const next = {
        ...(old ?? {}),
        id: old?.id ?? uid(),
        type: data.type ?? old?.type ?? 'login',
        name: data.name ?? old?.name ?? '',
        favorite: old?.favorite ?? false,
        revisionDate: new Date().toISOString(),
      };
      for (const k of ['username', 'password', 'totp', 'notes', 'card', 'identity']) if (data[k] !== undefined) next[k] = data[k] || undefined;
      if (data.uris !== undefined) next.uris = data.uris;
      if (data.fields !== undefined) next.fields = data.fields;
      if (data.folderId !== undefined) next.folderId = data.folderId || null;
      if (data.passkeys !== undefined) next.passkeys = data.passkeys;
      next.uris ??= [];
      next.fields ??= [];
      next.subtitle = subtitle(next);
      if (old && old.password && next.password !== old.password) {
        next.passwordHistory = [{ password: old.password, lastUsedDate: new Date().toISOString() }, ...(old.passwordHistory ?? [])].slice(0, 5);
      }
      if (old) v.items[v.items.indexOf(old)] = next; else v.items.push(next);
      commit();
      return { item: present(meta, config, v, next) };
    },

    async deleteItem(config, session, existing) {
      const v = vaultOf(config);
      const gone = v.items.find((i) => i.id === existing.id);
      v.items = v.items.filter((i) => i.id !== existing.id);
      if (gone && caps.restore) v.trash.unshift({ ...gone, deletedDate: new Date().toISOString() });
      commit();
      return { deletedId: existing.id };
    },

    async createFolder(config, session, { name }) {
      const v = vaultOf(config);
      const folder = { id: uid(), name };
      v.folders.push(folder);
      commit();
      return { folder };
    },
  };

  if (caps.favorites !== false) {
    p.setFavorite = async (config, session, existing, favorite) => {
      const v = vaultOf(config);
      const it = v.items.find((i) => i.id === existing.id);
      if (it) it.favorite = !!favorite;
      commit();
      return { item: present(meta, config, v, it ?? existing) };
    };
  }

  if (caps.restore) {
    p.restoreItem = async (config, session, existing) => {
      const v = vaultOf(config);
      const it = v.trash.find((i) => i.id === existing.id);
      v.trash = v.trash.filter((i) => i.id !== existing.id);
      if (it) { delete it.deletedDate; v.items.push(it); }
      commit();
      return { item: present(meta, config, v, it ?? existing) };
    };
    p.purgeItem = async (config, session, existing) => {
      const v = vaultOf(config);
      v.trash = v.trash.filter((i) => i.id !== existing.id);
      commit();
      return { purgedId: existing.id };
    };
  }

  if (caps.share) {
    // Passbolt: permission types 1 = read, 7 = update, 15 = owner
    const PEOPLE = [
      { aro: 'User', aroId: 'u-ada', name: 'Ada Lovelace', sub: 'ada@example.com' },
      { aro: 'User', aroId: 'u-grace', name: 'Grace Hopper', sub: 'grace@example.com' },
      { aro: 'User', aroId: 'u-alan', name: 'Alan Turing', sub: 'alan@example.com' },
      { aro: 'Group', aroId: 'g-ops', name: 'Operations', sub: 'Gruppe' },
    ];
    p.permissions = async (config, session, item) => {
      const v = vaultOf(config);
      const it = v.items.find((i) => i.id === item.id);
      it.permissions ??= [{ id: uid(), ...PEOPLE[0], type: 15 }];
      commit();
      return { permissions: structuredClone(it.permissions) };
    };
    p.shareTargets = async (config, session, query) => {
      const q = String(query ?? '').toLowerCase();
      return { targets: PEOPLE.filter((x) => `${x.name} ${x.sub}`.toLowerCase().includes(q)) };
    };
    p.share = async (config, session, item, changes) => {
      const v = vaultOf(config);
      const it = v.items.find((i) => i.id === item.id);
      let perms = it.permissions ?? [];
      for (const c of changes) {
        if (c.id && c.delete) perms = perms.filter((x) => x.id !== c.id);
        else if (c.id) perms = perms.map((x) => (x.id === c.id ? { ...x, type: c.type } : x));
        else perms.push({ id: uid(), ...PEOPLE.find((x) => x.aroId === c.aroId), type: c.type });
      }
      it.permissions = perms;
      commit();
      return {};
    };
  }

  return p;
}
